(() => {
  const path = location.pathname;
  const isEs = path.includes('/es/');

  const insertBefore = (target, node) => target?.parentNode?.insertBefore(node, target);

  if (path.includes('canarias7-articulo-30mayo2022') || path.includes('canarias7-article-30may2022')) {
    const messageSection = document.querySelector('#mensaje, #message');
    if (messageSection && !document.querySelector('[data-fiscal-estevez-update]')) {
      const heading = messageSection.querySelector('h2');
      if (heading) {
        heading.textContent = isEs
          ? 'A Francisco José Fajardo, a Francisco Suárez Álamo, director de Canarias7, a Informaciones Canarias, S.A., y al fiscal Luis Estévez'
          : 'To Francisco José Fajardo, Canarias7 director Francisco Suárez Álamo, Informaciones Canarias, S.A., and prosecutor Luis Estévez';
      }
      const p = document.createElement('p');
      p.dataset.fiscalEstevezUpdate = 'true';
      p.className = 'safe';
      p.innerHTML = isEs
        ? '<strong>Fiscal Luis Estévez.</strong> La pieza preservada identifica expresamente a Luis Estévez como el fiscal que suscribió el escrito de acusación. Además, esta parte conoce directamente que fue el fiscal que llevó esa acusación en aquel momento. Por ello le incluimos expresamente en este mensaje público: no para atribuirle responsabilidad por la posterior despublicación, sino para invitarle a confirmar el procedimiento, el escrito fiscal, el alcance de la acusación y, si le consta, su desenlace procesal.'
        : '<strong>Prosecutor Luis Estévez.</strong> The preserved report expressly identifies Luis Estévez as the prosecutor who signed the prosecution filing. In addition, this side has direct knowledge that he was the prosecutor handling that accusation at the relevant time. We therefore include him expressly in this public message: not to attribute responsibility for the later unpublishing, but to invite confirmation of the proceeding, the prosecution filing, the scope of the accusation and, if known to him, its procedural outcome.';
      const firstP = messageSection.querySelector('.shell > p:not(.eyebrow)');
      if (firstP) firstP.after(p); else messageSection.querySelector('.shell')?.appendChild(p);
    }

    const factParas = [...document.querySelectorAll('#articulo .mcard p, #article .mcard p')];
    const fiscalPara = factParas.find(p => /Luis Estévez/.test(p.textContent || ''));
    if (fiscalPara) {
      fiscalPara.innerHTML = isEs
        ? 'El texto atribuía a la Fiscalía Provincial de Las Palmas una acusación contra la consejera delegada de Construcciones Acosta Matos por presunta falsificación documental y tentativa de estafa procesal en una controversia comercial de 2015. Identificaba expresamente al <strong>fiscal Luis Estévez</strong> como quien suscribía el escrito de acusación; esta parte conoce directamente que fue el fiscal que llevó esa acusación en aquel momento.'
        : 'The article attributed to the Las Palmas Provincial Prosecutor’s Office an accusation against the chief executive of Construcciones Acosta Matos for alleged document falsification and attempted procedural fraud in a separate 2015 commercial dispute. It expressly identified <strong>prosecutor Luis Estévez</strong> as the prosecutor who signed the prosecution filing; this side also has direct knowledge that he was the prosecutor handling that accusation at the relevant time.';
    }
  }

  if (path.includes('eleconomista-javier-romera-enero2025') || path.includes('eleconomista-javier-romera-january2025')) {
    const facts = document.querySelector('#hechos, #facts');
    if (facts && !document.querySelector('[data-pressrelease-summary]')) {
      const next = facts.nextElementSibling;
      const section = document.createElement('section');
      section.className = 'section alt';
      section.dataset.pressreleaseSummary = 'true';
      section.innerHTML = isEs
        ? `<div class="shell"><p class="eyebrow">QUÉ SE PROPONÍA PUBLICAR</p><h2>La nota de prensa de 16 de enero de 2025: el punto de partida editorial</h2><p>La propuesta enviada a Javier Romera llevaba por título «Fraude Multimillonario en la Comercialización de Hoteles en Canarias durante el Covid» y presentaba una tesis amplia de posible fraude sistémico alrededor de Sun Park, Construcciones Acosta Matos, financiación RIC, fondos europeos y relaciones de comercialización con Meeting Point/FTI. Era una <strong>nota de parte destinada a provocar investigación periodística</strong>, no una fuente independiente ni una relación de hechos judicialmente declarados.</p><div class="mgrid"><article class="mcard"><h3>Sun Park / CAM</h3><p>La nota alegaba que CAM había tomado control del hotel sin título suficiente, había utilizado documentación de deuda y titularidad de forma irregular y había convertido después el activo en base de una reforma y nueva explotación hotelera.</p></article><article class="mcard"><h3>Meeting Point / FTI</h3><p>Alegaba acuerdos de comercialización y explotación con Meeting Point y FTI Touristik y sostenía que esas relaciones debían examinarse junto con la financiación y los ingresos generados por el hotel.</p></article><article class="mcard"><h3>Financiación acumulada</h3><p>La nota afirmaba una posible superposición de tres ramas de financiación ligadas a la misma reforma: aproximadamente €3,5m de fondos europeos, €6,5m de capital RIC y €4,5m de costes de reforma imputados por vía judicial, presentándolo entonces como una exposición agregada de unos €14,5m.</p></article><article class="mcard"><h3>Fondos públicos y Covid</h3><p>También pedía investigar si las ayudas públicas recibidas por FTI en Baviera y por Meeting Point/SEPI tuvieron alguna conexión económica con los proyectos o relaciones comerciales descritos. La nota formulaba esa conexión como hipótesis de investigación, no como trazabilidad financiera demostrada.</p></article><article class="mcard"><h3>Dimensión política e institucional</h3><p>La nota vinculaba críticamente el diseño/promoción de vehículos RIC y la respuesta institucional canaria con responsables políticos de la época. Esa formulación era acusatoria y requería —y sigue requiriendo— separar decisiones públicas documentadas de cualquier inferencia de participación en ilícitos.</p></article></div><p class="safe"><strong>Lectura retrospectiva responsable:</strong> varias formulaciones de aquella nota eran demasiado categóricas. Lo relevante para esta página no es adoptarlas como verdad, sino explicar <strong>qué historia estaba contrastando elEconomista</strong>. El intercambio posterior muestra que Romera estaba trabajando hacia una publicación, condicionada a revisar resoluciones y tener los extremos «bien atados», antes de comunicar el 20 de enero que el auto recibido cambiaba la decisión editorial.</p></div>`
        : `<div class="shell"><p class="eyebrow">WHAT WAS PROPOSED FOR PUBLICATION</p><h2>The 16 January 2025 press release: the editorial starting point</h2><p>The material sent to Javier Romera was headed “Fraude Multimillonario en la Comercialización de Hoteles en Canarias durante el Covid” and advanced a broad thesis of possible systemic wrongdoing around Sun Park, Construcciones Acosta Matos, RIC financing, European funds and commercialisation relationships with Meeting Point/FTI. It was a <strong>party-authored press release intended to trigger journalistic investigation</strong>, not an independent source or a statement of judicially established facts.</p><div class="mgrid"><article class="mcard"><h3>Sun Park / CAM</h3><p>The release alleged that CAM had taken control of the hotel without sufficient title, had used debt/title documentation irregularly, and later used the asset as the basis for refurbishment and renewed hotel operation.</p></article><article class="mcard"><h3>Meeting Point / FTI</h3><p>It alleged commercialisation and operating arrangements with Meeting Point and FTI Touristik and argued that those relationships should be examined together with the financing and revenues generated by the hotel.</p></article><article class="mcard"><h3>Layered financing</h3><p>The release alleged possible overlap among three financing branches tied to the same refurbishment: about €3.5m in European funds, €6.5m in RIC capital and €4.5m in refurbishment costs attributed through judicial proceedings, then presenting the aggregate exposure as roughly €14.5m.</p></article><article class="mcard"><h3>Public funds and Covid</h3><p>It also called for investigation of whether public support received by FTI in Bavaria and by Meeting Point/SEPI had any economic connection to the projects or commercial relationships described. The release framed that connection as an investigative hypothesis, not demonstrated fund tracing.</p></article><article class="mcard"><h3>Political and institutional dimension</h3><p>The release critically connected the design/promotion of RIC vehicles and the Canarian institutional response with political office-holders of the period. That wording was accusatory and required —and still requires— separation of documented public decisions from any inference of participation in wrongdoing.</p></article></div><p class="safe"><strong>Responsible retrospective reading:</strong> several formulations in that press release were too categorical. Its relevance here is not to adopt them as established truth, but to explain <strong>what story elEconomista was investigating</strong>. The later exchange shows Romera was working toward publication, subject to reviewing court decisions and having the relevant points properly tied down, before communicating on 20 January that the order received changed the editorial decision.</p></div>`;
      if (next) insertBefore(next, section); else facts.after(section);
    }
  }
})();